from review import card,save,DATE
i='TCS-3566';_,c=card(i);refs=c['references'];refs[0]['locator']='Section 2, adaptive online model, Assumptions 3–4 and linear-optimization oracle; Theorems 7 and 13; Section 6, total-call complexity Tε and dimension-independent ε⁻³ question.'
refs += [dict(id='expconcave',title='Projection-free Online Exp-concave Optimization',authors='Dan Garber; Ben Kretzu',year=2023,url='https://proceedings.mlr.press/v195/garber23a.html',pdf_url='https://proceedings.mlr.press/v195/garber23a/garber23a.pdf',locator='Introduction and Table 1, dimensions in previous smooth-loss bounds; additional exp-concavity and low-dimensional-gradient assumptions in the improved results.'),dict(id='separation',title='Online Convex Optimization with a Separation Oracle',authors='Zakaria Mhammedi',year=2024,url='https://arxiv.org/abs/2410.02476',pdf_url='https://arxiv.org/pdf/2410.02476',locator='Version 2, 7 October 2024; abstract and problem setup, separation-oracle access and dimension/asphericity dependence.'),dict(id='constraints2026',title='Projection-free Algorithms for Online Convex Optimization with Adversarial Constraints',authors='Dhruv Sarkar; Aprameyo Chakrabartty; Subhamon Supantha; Palash Dey; Abhishek Sinha',year=2026,url='https://proceedings.mlr.press/v300/sarkar26a.html',locator='AISTATS 2026; abstract, one linear optimization call per round with regret and cumulative constraint violation of order T^{3/4} up to logarithms.')]
save(i,dict(title='Dimension-independent ε⁻³ oracle complexity for smooth online optimization',formal='Is there a projection-free randomized online algorithm whose total number of gradient and linear-optimization oracle calls needed to guarantee expected average regret at most ε is O(ε⁻³), uniformly over the ambient dimension and all compact convex decision sets? More precisely, for every fixed positive D,G,β, seek a bound C(D,G,β)ε⁻³, with C independent of d, the set K and the adversary, for every d≥1, every nonempty compact convex K⊆Rᵈ contained in the radius-D Euclidean ball, every 0<ε<1, and every adaptive sequence of convex β-smooth losses with gradient norm at most G. The algorithm’s guarantee must use only gradient access to revealed losses and linear optimization over K as described below. This is the source’s online average-regret question, not minimization of one fixed smooth function.',definitions='At round t the learner chooses xₜ∈K while the adversary chooses fₜ:K→R. The adversary may depend on the full previous history but cannot observe the learner’s fresh random choice at that round before fixing fₜ. Afterwards the loss is revealed and may be accessed through exact gradient evaluations at queried points of K; future losses are unavailable. Each fₜ is differentiable and convex, ‖∇fₜ(x)‖₂≤G, and ‖∇fₜ(x)−∇fₜ(y)‖₂≤β‖x−y‖₂ for all x,y∈K. After H rounds, regret is R_H=Σ_{t=1}^H fₜ(xₜ)−min_{x∈K}Σ_{t=1}^H fₜ(x). Expectation is over the learner’s randomness and any adversary randomness, including the resulting adaptive history; the required guarantee is E[R_H]/H≤ε. The algorithm may choose its horizon and parameters using ε,D,G,β and d, but its total oracle-call bound must hold uniformly in d and K. A linear-optimization call at v∈Rᵈ returns any maximizer of ⟨v,x⟩ over K; the support value is then obtained by an inner product. All returned points must be valid maximizers, and no special tie-breaking promise is available. Access to K is through this oracle and a feasible starting point, which can also be obtained by a zero-objective call. Every gradient evaluation and every linear-optimization invocation counts once, including initialization, internal repeated calls and calls on past losses. Projection, membership and separation are not additional free oracles. Internal vector arithmetic is not the resource being bounded; this is an exact real-oracle complexity question, not a dimension-independent bit-running-time claim. The displayed O bound hides neither dimension nor geometric conditioning of K, and does not hide logarithmic losses in ε. The target concerns total calls, without requiring exactly one call per online round.',question_type='yes_no',answer_criterion='Give one uniform online algorithm with a total-call bound C(D,G,β)ε⁻³ and expected average regret at most ε for every specified instance and adaptive adversary, or prove that such a uniform bound is impossible in this oracle model. A negative answer must rule out the uniform ε⁻³ bound, rather than merely exhibit a dimension factor in one existing analysis. An algorithm needing extra set geometry, a different free oracle, stronger loss assumptions or more total calls does not settle the target.',context_blocks=[dict(title='The combined oracle count is the stated resource',text='Section 6 counts both gradient computations and linear optimizations until average regret reaches ε. A regret rate alone is insufficient if achieving it requires many internal oracle calls. The source gives O(dε⁻³) for smooth losses and contrasts it with the previous ε⁻⁴ dependence.',citation='primary'),dict(title='Smooth losses and arbitrary sets are both part of the question',text='The source allows arbitrary compact convex feasible sets and an adaptive adversary. Fast results for a special polytope, a curved set, a fixed stochastic objective or strongly convex losses address different restrictions.',citation='primary'),dict(title='An improvement under extra assumptions',text='Garber and Kretzu obtain improved bounds for smooth exp-concave losses, with benefits when gradients approximately span a low-dimensional space. Exp-concavity and low-dimensional gradients are not assumptions of this card.',citation='expconcave'),dict(title='A different oracle changes the comparison',text='Mhammedi’s 2024 preprint gives guarantees using a separation oracle, with dimension and geometric parameters in the bounds. It does not supply the specified bound using only linear-optimization access to the set.',citation='separation'),dict(title='A newer constrained variant',text='The AISTATS 2026 adversarial-constraint paper uses linear optimization but has a T^{3/4} scale for general losses and an additional constraint-violation objective. Its stated result does not supply the uniform ε⁻³ guarantee here.',citation='constraints2026')],why='Would show whether the smoother-loss improvement in online learning can retain its oracle advantage in arbitrarily high dimension and over arbitrary feasible geometry.',references=refs,progress=[dict(date='2020',text='The source obtains smooth-loss total oracle complexity O(dε⁻³) and asks to remove d.',citation='primary'),dict(date='2023',text='Further T^{2/3}-scale bounds use exp-concavity, with improved dimension behaviour under restrictions on the gradients.',citation='expconcave'),dict(date='2024-10-07',text='A separation-oracle preprint studies another access model and retains dimension/geometric dependence.',citation='separation'),dict(date='2026',text='The checked adversarial-constraint result retains a T^{3/4} scale for general losses with one linear-optimization call per round.',citation='constraints2026')],status='open',status_note='Read the original adaptive game, oracle definitions, theorem statements and Section 6 complexity question. Checked the 2023 LOO comparison, 2024 separation-oracle model, and 2026 adversarial-constraint result; broader searches included stochastic, decentralized and matrix variants. No result matching the uniform smooth-loss, arbitrary-set total-call target was located as of 12 September 2026. Search is not exhaustive.',model_self_contained=True,requires_context=False,importance=dict(score=c['importance']['score'],method='editorial',reason='A general high-dimensional oracle-complexity barrier for online convex optimization with smooth losses. Existing score retained.',assessed_on=DATE),review_note='Recovered ε⁻³ as total gradient-plus-linear-oracle complexity for expected online average regret; defined adaptive timing and uniformity in dimension, and separated extra assumptions in later results.',working_summary=dict(sentences=['The learner repeatedly chooses a point in a convex set before seeing that round’s loss.','The question asks for expected average regret at most ε using O(ε⁻³) total gradient and linear-optimization calls.','Losses are smooth and convex, but the feasible set and its ambient dimension are arbitrary.','The source’s bound has an extra dimension factor, while later checked improvements use stronger loss assumptions or different oracles.','Resolving the question requires a bound uniform in dimension and feasible geometry, or a lower bound ruling out that uniform rate.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','expconcave','separation','constraints2026'])),notes=['Recovered online average-regret target and total-call metric, not offline iteration complexity.','Defined smoothness, adaptive timing, exact oracle access, parameter quantifiers and dimension-independent constants.','Distinguished exp-concavity, geometric assumptions, separation oracles and stochastic variants in subsequent work.'],checked_sources=[r['url'] for r in refs]+['https://arxiv.org/abs/2604.02505','https://www.jmlr.org/papers/volume26/24-2137/24-2137.pdf'])
